css:
.print-format { padding: 6mm !important; font-family: Calibri, Carlito, Arial, sans-serif !important; }
.print-format table.cho { width: 100% !important; border-collapse: collapse !important; table-layout: fixed; margin: 0 !important; font-family: Calibri, Carlito, Arial, sans-serif !important; font-size: 11px !important; color: #000 !important; }
.print-format table.cho td { padding: 1px 4px !important; height: 18px !important; line-height: 15px !important; vertical-align: middle !important; white-space: nowrap; overflow: hidden; border: none; }
.print-format table.cho td.title { background: #FFC000 !important; color: #000 !important; text-align: center; font-weight: bold; font-size: 19px !important; height: 28px !important; border: 1px solid #000 !important; }
.print-format table.cho td.band { background: #333F4F !important; color: #FFC000 !important; text-align: center; font-weight: bold; font-size: 16px !important; height: 25px !important; border: 1px solid #000 !important; }
.print-format table.cho tr.colhead td { background: #D9D9D9 !important; font-weight: bold; border: 1px solid #000 !important; }
.print-format table.cho tr.colhead td.center { text-align: center; }
.print-format table.cho td.cell, .print-format table.cho td.box { border: 1px solid #000 !important; }
.print-format table.cho tr td.plain, .print-format table.cho tr td.gap { border: none !important; background: transparent !important; }
.print-format table.cho tr.total td.cell { background: #FFC000 !important; font-weight: bold; border-top: 2px solid #000 !important; border-bottom: 2px solid #000 !important; }
.print-format table.cho tr.total td.nobg { background: #fff !important; border: 1px solid #000 !important; }
.print-format table.cho td.big { font-size: 17px !important; }
.print-format table.cho .right { text-align: right !important; }
.print-format table.cho .bold { font-weight: bold !important; }
.print-format table.cho .red-text { color: #FF0000 !important; }
.print-format table.cho td { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.print-format .cho-letterhead { margin-bottom: 6px; text-align: center; }
.print-format .cho-letterhead img { max-height: 110px; }
